function sameQuestionnaireSnapshot(previous,next,instructions){
 if(!previous||previous.title!==next.title||!instructions.includes(previous.requirements?.instructions))return false;
 if(['materials','references','outline'].some(field=>previous[field]?.length))return false;
 const profile=previous.profile||{};
 if((profile.level??'本科')!=='本科'||(profile.major??'')!==''||profile.language!=='中文'||profile.targetWords!==500||Object.keys(profile).some(key=>!['level','major','language','targetWords'].includes(key)))return false;
 const before=previous.requirements||{},after=next.requirements;
 if(Object.keys(before).some(key=>!['instructions','outputCount','scalePoints','targetSampleSize','researchDimensions','analysisFocus'].includes(key)))return false;
 try{if(requestedQuestionCount(before)!==after.outputCount||requestedScalePoints(before)!==after.scalePoints)return false;}catch{return false;}
 return ['targetSampleSize','researchDimensions','analysisFocus'].every(field=>(before[field]??undefined)===(after[field]??undefined));
}
export async function createQuestionnaireQrDataURL(url,loadQr=()=>import(new URL('../vendor/payment-qr.mjs',import.meta.url).href)){
 const {toDataURL}=await loadQr();
 const value=await toDataURL(url,{width:244,margin:2,errorCorrectionLevel:'M',color:{dark:'#12213aff',light:'#ffffffff'}});
 if(typeof value!=='string'||!/^data:image\/png;base64,[A-Za-z0-9+/=]+$/.test(value))throw Error('问卷二维码生成未完成，请重试。');
 return value;
}
// Legacy five-level title helper; current adoption preserves every verbal option.
export function aiQuestionnaireScaleTitle(value,options){
 const title=String(value??'').trim();
 if(!Array.isArray(options)||options.length!==5||options.some(option=>typeof option!=='string'||!option.trim()))return title;
 const labels=options.map(option=>option.trim());if(new Set(labels).size!==5||labels.every(option=>/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(option)))return title;
 const normalized=title.normalize('NFKC'),compact=normalized.replace(/\s/g,''),escape=value=>value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
 const defined=(score,label)=>new RegExp('(?:^|[^0-9])'+score+'\\s*(?:分\\s*)?(?:[=＝:：]|表示|代表|为|是)\\s*[^\\s,，;；)）]+','u').test(normalized)||new RegExp('(?:^|[^0-9])'+score+'(?:分)?'+escape(label.normalize('NFKC').replace(/\s/g,'')),'iu').test(compact);
 const anchors=[[1,labels[0]],[5,labels[4]]].filter(([score,label])=>!defined(score,label)).map(([score,label])=>`${score} 分＝${label}`);if(!anchors.length)return title;
 const result=title+'（'+anchors.join('；')+'）';if(result.length>500)throw Error('量表题目与端点说明合计超过 500 字，请缩短问题后再采用。');return result;
}
