 function planningIssue(field){for(const [key,min,max,label]of [['questionCount',3,60,'AI 题数'],['targetSampleSize',1,1000,'计划样本量']]){if(field&&field!==key)continue;const value=content[key];if(value!==undefined&&value!==null&&value!==''&&(!Number.isSafeInteger(Number(value))||Number(value)<min||Number(value)>max))return `${label}须为 ${min}～${max} 的整数。`;}for(const [key,label]of [['researchDimensions','研究维度'],['analysisFocus','后续分析重点']])if((!field||field===key)&&String(content[key]??'').length>2000)return `${label}最多 2,000 字符，请精简后保存。`;return '';}
