 async function loadReport(){if(!item)return;const capturedId=item.id,capturedOpening=opening,capturedOwner=ownerId,capturedScope=scopeRevision,ticket=++reportRevision,pub=$('#q-report-version')?.value||reportPub||item.publications[0]?.id;const same=()=>current()&&item?.id===capturedId&&opening===capturedOpening&&ownerId===capturedOwner&&scopeRevision===capturedScope&&reportRevision===ticket&&reportPub===pub;if(!pub){report=null;draw();return;}reportPub=pub;report=null;try{await assertIdentity();if(!same())return;const ownerQuery='&expectedUserId='+encodeURIComponent(capturedOwner),result=await api('/questionnaires/'+capturedId+'/report?publication='+encodeURIComponent(pub)+ownerQuery);if(!same())return;if(result.report&&(result.report.publicationId!==pub||!item.publications.some(row=>row.id===pub&&row.version===result.report.version)))throw Error('统计报告版本无法核对，请重新读取。');const freshItem=(await api('/questionnaires/'+capturedId+'?expectedUserId='+encodeURIComponent(capturedOwner))).item;if(!same())return;report=result.report;item=freshItem;draw();}catch(error){if(same())throw error;}}
