   if(button.hasAttribute('data-q-ai')){if(!content.title.trim())throw Error('请先填写问卷主题。');if(!panel)panel=mountWritingJobPanel({container:$('#questionnaire-ai'),ctx,kind:'questionnaire',operation:'questionnaire',getSnapshot:snapshot,getProjectRef:()=>projectId||'',initialState:restoredAiState(content.aiState),isCurrent:current,onStateChange:async state=>{const expectedOwner=ownerId,expectedOpening=opening,expectedScope=scopeRevision;if(!current()||!loaded||!expectedOwner||state.ownerId&&state.ownerId!==expectedOwner)throw Error('问卷账户已变化，未提交生成任务。');content.aiState={...state};delete content.aiState.contextKey;changed();if(!await save()||!current()||ownerId!==expectedOwner||opening!==expectedOpening||scopeRevision!==expectedScope)throw Error('问卷任务恢复信息未能保存，请重试保存后再生成。');return true;},onApply:async output=>{const parsed=normalizeAIQuestionnaire(output,snapshot().requirements);content.questions=parsed.questions.map(q=>({...q,id:crypto.randomUUID()}));content.introduction=parsed.introduction;delete content.aiState;step=1;changed();draw();if(!await save())throw Error('问卷结果仍保留在编辑区，请重试保存；尚未保存到账户。');panel?.dispose();panel=null;$('#questionnaire-ai').hidden=true;}});await panel.open();return;}
