   if(button.hasAttribute('data-q-close')){if(!await save())return;const capturedId=item.id,capturedVersion=item.version,capturedOpening=opening,capturedOwner=ownerId;await assertIdentity();if(!current()||item?.id!==capturedId||opening!==capturedOpening||ownerId!==capturedOwner)return;const closed=(await api('/questionnaires/'+capturedId+'/close',{version:capturedVersion,expectedUserId:capturedOwner})).item;if(!current()||item?.id!==capturedId||opening!==capturedOpening)return;qrRevision++;qrImage=null;item=closed;status='已停止收集，已有答卷仍保留';draw();return;}
