function reportText(report){return `${report.title}\n真实答卷分析报告\n发布版本：${report.version}\n实际答卷：${report.total}\n统计时间：${report.generatedAt}\n\n${report.questions.map((q,index)=>`${index+1}. ${q.title}\n已答 ${q.answered}，未答 ${q.missing}${q.mean!==undefined?'，量表均值 '+(q.mean??'—'):''}\n${q.distribution?q.distribution.map(row=>`${row.option}：${row.count}（${row.percent}%）`).join('\n'):q.textAnswers.map((text,i)=>`${i+1}) ${text}`).join('\n')}${q.textAnswersLimited?'\n开放题回答仅列出本发布版本最新 50 条，完整答卷请导出 CSV。':''}${q.note?'\n'+q.note:''}`).join('\n\n')}\n\n${report.limitations}`;}
